import React, { useState } from "react";
import axios from "axios";

const PredictionPage = () => {
  const [inputData, setInputData] = useState({
    feature1: "",
    feature2: "",
    feature3: "",
    feature4: "",
    feature5: "",
    feature6: "",
  });
  const [modelType, setModelType] = useState("rf");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setInputData({ ...inputData, [e.target.name]: e.target.value });
  };

  const handleModelChange = (e) => {
    setModelType(e.target.value);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const values = Object.values(inputData).map(Number);

    if (values.some(isNaN)) {
      alert("Please enter valid numbers in all fields.");
      return;
    }

    setLoading(true);
    try {
      const res = await axios.post("http://localhost:5000/predict", {
        inputData: values,
        modelType,
      });
      setResult(res.data.prediction === 1 ? "Alzheimer's Detected" : "No Alzheimer's Detected");
    } catch (error) {
      console.error(error);
      setResult("Error occurred during prediction.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: "2rem", fontFamily: "Arial" }}>
      <h2>Alzheimer's Disease Prediction</h2>
      <form onSubmit={handleSubmit}>
        {Object.keys(inputData).map((key, idx) => (
          <div key={key}>
            <label>
              Feature {idx + 1}:{" "}
              <input
                type="number"
                name={key}
                value={inputData[key]}
                onChange={handleChange}
                required
              />
            </label>
          </div>
        ))}

        <div>
          <label>Select Model: </label>
          <select value={modelType} onChange={handleModelChange}>
            <option value="rf">Random Forest</option>
            <option value="svm">SVM</option>
            <option value="cnn">CNN</option>
          </select>
        </div>

        <button type="submit" disabled={loading}>
          {loading ? "Predicting..." : "Predict"}
        </button>
      </form>

      {result && (
        <div style={{ marginTop: "1rem", fontWeight: "bold" }}>
          Prediction Result: {result}
        </div>
      )}
    </div>
  );
};

export default PredictionPage;
